import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"5.1 Create visible memory","description":"Remember useful information and explain its source and use.","frontmatter":{"title":"5.1 Create visible memory","description":"Remember useful information and explain its source and use.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-5/5-1.md","filePath":"en/delivery/stage-5/5-1.md","lastUpdated":1794015952000}'),i={name:"en/delivery/stage-5/5-1.md"};function s(n,e,l,d,m,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_5-1-create-visible-memory" tabindex="-1">5.1 Create visible memory <a class="header-anchor" href="#_5-1-create-visible-memory" aria-label="Permalink to &quot;5.1 Create visible memory&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Implemented:</strong> Memory enters a candidate state and is recalled only after confirmation; records keep type, topic key, scope, tags, provenance, confidence, sensitivity, expiry, and version; recall records reasons and usage audits, and injected context carries <code>trusted=&quot;false&quot;</code> plus a no-privilege-expansion boundary.</li><li><strong>Still open:</strong> Automatic capture is off by default and only captures &quot;experience&quot; memory from finished tasks; there is no automatic extraction of user facts from email, the web, or arbitrary documents.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth remember information that is genuinely useful to the user and explain where each memory came from and why it was used. The user must be able to view and edit these memories.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Record user facts, project context, preferences, commitments, and past task experience, but only with a source.</li><li>Each memory states its source, time, confidence, scope, and sensitivity.</li><li>Provide a memory browser where the user can see what was remembered and where it was recently used.</li><li>When a task uses memory, explain which items were used and why they were relevant; avoid a black box.</li><li>Give the execution only the minimum background the task needs; do not dump every memory into every task.</li><li>After the user edits or deletes a memory, later tasks use the new version immediately.</li></ol>',7)])])}const p=t(i,[["render",s]]);export{h as __pageData,p as default};
